146: void llama_memory_hybrid_idx::clear(bool data) {
147:     llama_memory_hybrid::clear(data);
148: 
149:     if (mem_idx) {
150:         mem_idx->clear(data);
151:         mem_idx_stale_set(-1, 0);
152:     }
153: }
