155: // A pooled key is only valid while the grouping that produced it holds. Grouping is sequence relative,
156: // so an edit at p0 leaves every pool that ends before p0 alone.
157: void llama_memory_hybrid_idx::mem_idx_stale_set(llama_seq_id seq_id, llama_pos p0) {
158:     p0 = std::max<llama_pos>(p0, 0);
159: 
160:     if (seq_id < 0) {
161:         for (auto & p : mem_idx_stale) {
162:             p = std::min(p, p0);
163:         }
164: 
165:         return;
166:     }
167: 
168:     GGML_ASSERT(seq_id < (llama_seq_id) LLAMA_MAX_SEQ);
169: 
170:     mem_idx_stale[seq_id] = std::min(mem_idx_stale[seq_id], p0);
171: }
