173: // An edit at or below the first position moves pos_min, which regroups the whole sequence.
174: llama_pos llama_memory_hybrid_idx::mem_idx_stale_pos(llama_seq_id seq_id, llama_pos p0) const {
175:     if (seq_id < 0 || p0 <= mem_idx->seq_pos_min(seq_id)) {
176:         return 0;
177:     }
178: 
179:     return p0;
180: }
