182: bool llama_memory_hybrid_idx::seq_rm(llama_seq_id seq_id, llama_pos p0, llama_pos p1) {
183:     // same order as llama_memory_hybrid::seq_rm: the recurrent cache can refuse, so try it first
184:     if (!get_mem_recr()->seq_rm(seq_id, p0, p1)) {
185:         return false;
186:     }
187: 
188:     if (mem_idx) {
189:         const llama_pos stale = mem_idx_stale_pos(seq_id, p0);
190:         mem_idx->seq_rm(seq_id, p0, p1);
191:         mem_idx_stale_set(seq_id, stale);
192:     }
193: 
194:     return get_mem_attn()->seq_rm(seq_id, p0, p1);
195: }
