197: void llama_memory_hybrid_idx::seq_cp(llama_seq_id seq_id_src, llama_seq_id seq_id_dst, llama_pos p0, llama_pos p1) {
198:     // only whole sequences are copied: the recurrent state ignores the range, and a shared cell holds a single pool grouping
199:     GGML_ASSERT(p0 <= 0 && p1 < 0 && "partial seq_cp is not supported");
200: 
201:     llama_memory_hybrid::seq_cp(seq_id_src, seq_id_dst, p0, p1);
202: 
203:     if (mem_idx) {
204:         mem_idx->seq_cp(seq_id_src, seq_id_dst, p0, p1);
205:         // a whole sequence copy gives the destination the source's pools, rep rows included: the source keeps its
206:         // pooled keys, the destination rebuilds its layout and re-pools into the same rows
207:         mem_idx_stale_set(seq_id_dst, 0);
208:     }

253: void llama_memory_hybrid_idx::state_write(llama_io_write_i & io, llama_seq_id seq_id, llama_state_seq_flags flags) const {
254:     llama_memory_hybrid::state_write(io, seq_id, flags);
255: 
256:     // [TAG_HYBRID_IDX_STATE] the indexer section goes last, so it is a pure suffix: an old reader stops early instead of misparsing it
257:     if (mem_idx) {
258:         mem_idx->state_write(io, seq_id, flags);
259:     }
260: }
