262: void llama_memory_hybrid_idx::state_read(llama_io_read_i & io, llama_seq_id seq_id, llama_state_seq_flags flags) {
263:     // note: repeats llama_memory_hybrid::state_read
264:     // the indexer needs the attention cache's cells, and a half-failed restore must leave all three caches alike
265: 
266:     // [TAG_HYBRID_IDX_SINFO]
267:     // the indexer restore adopts the attention cache's layout instead of searching for cells of its own
268:     // two find_slot calls agree only while both caches see the same occupancy, which a restore cannot promise
269:     llama_kv_cache::slot_info_vec_t sinfos_attn;
270: 
271:     try {
272:         // the indexer cache has the SWA type of the attention cache, so both read the same partial state
273:         get_mem_attn()->state_read_sinfo(io, seq_id, flags, mem_idx ? &sinfos_attn : nullptr, nullptr);
274: 
275:         get_mem_recr()->state_read(io, seq_id, flags);
276: 
277:         // [TAG_HYBRID_IDX_STATE] must mirror the write order in state_write
278:         if (mem_idx) {
279:             mem_idx->state_read_sinfo(io, seq_id, flags, nullptr, &sinfos_attn);
280:             // a restore that rewrites cells does it behind the pool layout's back
281:             if (!sinfos_attn.empty()) {
282:                 mem_idx_stale_set(seq_id, 0);
283:             }
284:         }
285: 
286:     } catch (...) {
287:         // a half-restored context is the one state the indexer cannot fix by itself: attention holds new cells, the indexer old ones
288:         // drop what was being restored from all of them, which is a state they do agree on.
289:         state_drop(seq_id);
290: 
291:         throw;
292:     }
293: }
