295: void llama_memory_hybrid_idx::state_drop(llama_seq_id seq_id) {
296:     // dropped directly, not via seq_rm: the recurrent cache may refuse it and then only the other two get cleared
297:     if (seq_id < 0) {
298:         clear(true);
299: 
300:         return;
301:     }
302: 
303:     get_mem_attn()->state_clear(seq_id);
304:     get_mem_recr()->seq_rm(seq_id, -1, -1);
305: 
306:     if (mem_idx) {
307:         mem_idx->state_clear(seq_id);
308:         mem_idx_stale_set(seq_id, 0);
309:     }

