384: // Pools are fixed by the positions relative to the sequence's first one, so the layout survives a plain
385: // append. A sequence edit can regroup them, and mem_idx_stale tells us it happened.
386: const llama_memory_hybrid_idx::kpool_layout & llama_memory_hybrid_idx::kpool_layout_update() {
387:     GGML_ASSERT(mem_idx != nullptr);
388: 
389:     if (!kpool_lay) {
390:         kpool_lay = std::make_unique<kpool_layout>();
391:     }
392: 
393:     auto & lay = *kpool_lay;
394: 
395:     const uint32_t kpool       = get_kpool();
396:     const uint32_t n_stream_kv = mem_idx->get_n_stream();
397:     const bool     unified     = n_stream_kv == 1;
398: 
399:     lay.n_pool_real = 0;
400: 
401:     for (llama_seq_id s = 0; s < LLAMA_MAX_SEQ; ++s) {
402:         auto & sq = lay.seqs[s];
403: 
404:         // a non unified cache gives each sequence its own stream, with stream local cell indices
405:         if (!unified && s >= (llama_seq_id) n_stream_kv) {
406:             sq = kpool_layout::seq();
407:             continue;
408:         }
409: 
410:         const auto & cells = mem_idx->get_cells(unified ? 0 : s);
411:         const auto & sp    = cells.seq_pos_get(s);
412: 
413:         sq.strm = unified ? 0 : mem_idx->get_stream(s);
414: 
415:         if (mem_idx_stale[s] == POS_CLEAN && !sq.cells.empty() && !sp.empty() &&
416:                 sq.pos_min == sp.begin()->first) {
417:             for (auto it = sp.upper_bound(sq.cells.back()); it != sp.end(); ++it) {
418:                 sq.cells.push_back(*it);
419:             }
420:         }
421: 
422:         // the appended tail accounts for every cell only if nothing before it was dropped, but an edit can
423:         // regroup a sequence without changing its cell count, so a stale sequence must rebuild regardless
424:         if (sq.cells.size() != sp.size() || mem_idx_stale[s] != POS_CLEAN) {
425:             sq.cells.assign(sp.begin(), sp.end());
426:             sq.pools.clear();
427:             sq.j_next  = 0;
428:             sq.pos_min = sp.empty() ? 0 : sp.begin()->first;
429:         }
430: 
431:         // Pools start at the first valid token
432:         size_t j = sq.j_next;
433:         if (hparams_idx.indexer_kpool_by_order) {
434:             // consecutive cells in sequence order, whatever their positions
435:             for (; j + kpool <= sq.cells.size(); j += kpool) {
436:                 sq.pools.push_back((uint32_t) j);
437:             }
438:         } else {
439:             while (j + kpool <= sq.cells.size()) {
440:                 const llama_pos p0 = sq.cells[j].first;
441:                 if ((p0 - sq.pos_min) % (llama_pos) kpool != 0) {
442:                     ++j;
443:                     continue;
444:                 }
445:                 bool ok = true;
446:                 for (uint32_t k = 1; k < kpool; ++k) {
447:                     if (sq.cells[j + k].first != p0 + (llama_pos) k) {
448:                         ok = false;
449:                         break;
450:                     }
451:                 }
452:                 if (ok) {
453:                     sq.pools.push_back((uint32_t) j);
454:                     j += kpool;

166: bool llama_memory_recurrent::seq_rm(llama_seq_id seq_id, llama_pos p0, llama_pos p1) {
167:     uint32_t new_head = size;
168: 
169:     if (p0 < 0) {
170:         p0 = 0;
171:     }
172: 
173:     if (p1 < 0) {
174:         p1 = std::numeric_limits<llama_pos>::max();
175:     }
176: 
177:     if ((uint32_t) seq_id >= this->n_seq_max) {
178:         LLAMA_LOG_ERROR("%s: invalid seq_id (%d) - larger than n_seq_max (%d)\n", __func__, seq_id, this->n_seq_max);
179:         return false;
180:     }
181: 
182:     const bool rm_all = p0 == 0 && p1 == std::numeric_limits<llama_pos>::max();
183:     if (rm_all) {
184:         set_rs_idx(seq_id, 0);
185:     }
186: 
187:     // models like Mamba or RWKV can't have a state partially erased at the end
188:     // of the sequence because their state isn't preserved for previous tokens
189:     if (seq_id >= (int64_t) size) {
190:         // could be fatal
191:         return false;
192:     }
193:     if (0 <= seq_id) {
194:         int32_t & tail_id = cells[seq_id].tail;
195:         if (tail_id >= 0) {
196:             auto & cell = cells[tail_id];
197: 
198:             // partial rollback via per-token snapshot index (bounded by the snapshots of the last ubatch)
199:             if (0 < p0 && p0 <= cell.pos && p1 > cell.pos) {
200:                 // a cell shared by several sequences cannot move back for only one of them
201:                 if (cell.seq_id.size() > 1) {
202:                     return false;
203:                 }
204:                 // the filter kept no layer (e.g. an MTP draft context), so only the position moves back
205:                 if (is_empty()) {
206:                     cell.pos = p0 - 1;
207:                     return true;
208:                 }
209:                 const llama_pos rollback = cell.pos - (p0 - 1);
210:                 // pending rollback is single-use
211:                 const bool pending = rs_idx[seq_id] != 0;
212:                 if (!pending && rollback >= 1 && rollback <= (llama_pos) cell.rs_max) {
213:                     set_rs_idx(seq_id, (uint32_t) rollback);
214:                     cell.pos = p0 - 1;
215:                     return true;
216:                 }
217:                 return false;
218:             }
219:             // invalidate tails which will be cleared
220:             if (p0 <= cell.pos && cell.pos < p1) {
221:                 tail_id = -1;
222:             }
223:         }
224:     } else {
225:         // seq_id is negative, then the range should include everything or nothing
226:         if (p0 != p1 && (p0 != 0 || p1 != std::numeric_limits<llama_pos>::max())) {
227:             //printf("[DEBUG] inside `llama_memory_recurrent::seq_rm`: `seq_id` is negative, so returning false\n");
228:             return false;
229:         }
230:     }
231: 
232:     for (uint32_t i = 0; i < size; ++i) {
233:         if (cells[i].pos >= p0 && cells[i].pos < p1) {
234:             if (seq_id < 0) {
235:                 cells[i].seq_id.clear();
236:             } else if (cells[i].has_seq_id(seq_id)) {
237:                 cells[i].seq_id.erase(seq_id);
238:             } else {
239:                 continue;
240:             }
241:             if (cells[i].is_empty()) {
242:                 // keep count of the number of used cells
243:                 if (cells[i].pos >= 0) {
244:                     used--;
245:                 }
246:                 cells[i].pos = -1;
247:                 cells[i].src = -1;
248:                 if (new_head == size) {
249:                     new_head = i;
250:                 }
251:             }
252:         }
253:     }
