783: void llama_memory_recurrent::state_write(llama_io_write_i & io, llama_seq_id seq_id, llama_state_seq_flags flags) const {
784:     GGML_UNUSED(flags);
785: 
786:     std::vector<std::pair<uint32_t, uint32_t>> cell_ranges; // ranges, from inclusive, to exclusive
787:     std::vector<std::pair<uint32_t, uint32_t>> cell_ranges_data; // logical source row ranges
788:     uint32_t cell_count = 0;
789: 
790:     // Count the number of cells with the specified seq_id
791:     // Find all the ranges of cells with this seq id (or all, when -1)
792:     uint32_t cell_range_begin = size;
793:     for (uint32_t i = 0; i < size; ++i) {
794:         const auto & cell = cells[i];
795:         // TODO: fix incosistent handling of `seq_id < 0` and `seq_id == -1` in the codebase [TAG_LLAMA_SEQ_ID_NEG]
796:         if ((seq_id == -1 && !cell.is_empty()) || cell.has_seq_id(seq_id)) {
797:             ++cell_count;
798:             uint32_t rs_idx_cur = 0;
799: 
800:             if (n_rs_seq != 0) {
801:                 if (seq_id != -1) {
802:                     GGML_ASSERT(seq_id >= 0 && (size_t) seq_id < rs_idx.size());
803:                     rs_idx_cur = rs_idx[seq_id];
804:                 } else {
805:                     bool has_rs_idx = false;
806:                     for (const llama_seq_id cell_seq_id : cell.seq_id) {
807:                         GGML_ASSERT(cell_seq_id >= 0 && (size_t) cell_seq_id < rs_idx.size());
808: 
809:                         const uint32_t seq_rs_idx = rs_idx[cell_seq_id];
810:                         if (!has_rs_idx) {
811:                             rs_idx_cur = seq_rs_idx;
812:                             has_rs_idx = true;
813:                         } else if (rs_idx_cur != seq_rs_idx) {
814:                             GGML_ABORT("cannot write shared recurrent state with different rollback indices");
815:                         }
816:                     }
817:                 }
818:             }
819: 
820:             const uint32_t cell_id = rs_idx_cur * size + (cell.src >= 0 ? cell.src : (int32_t) i);
821:             if (cell_ranges_data.empty() || cell_ranges_data.back().second != cell_id) {
822:                 cell_ranges_data.emplace_back(cell_id, cell_id + 1);
823:             } else {
824:                 cell_ranges_data.back().second++;
825:             }
826: 
827:             if (cell_range_begin == size) {
828:                 cell_range_begin = i;
829:             }
830:         } else {
831:             if (cell_range_begin != size) {
832:                 cell_ranges.emplace_back(cell_range_begin, i);
833:                 cell_range_begin = size;
834:             }
835:         }
836:     }
837:     if (cell_range_begin != size) {
838:         cell_ranges.emplace_back(cell_range_begin, size);
839:     }
840: 
841:     if ((flags & LLAMA_STATE_SEQ_FLAGS_ON_DEVICE) && cell_ranges.size() > 1) {
842:         GGML_ABORT("cannot save/load multiple ranges of cells to/from device memory\n");
843:     }
844: 
845:     // DEBUG CHECK: Sum of cell counts in ranges should equal the total cell count
846:     uint32_t cell_count_check = 0;
847:     for (const auto & range : cell_ranges) {
848:         cell_count_check += range.second - range.first;
849:     }
850:     GGML_ASSERT(cell_count == cell_count_check);
851: 
852:     cell_count_check = 0;
853:     for (const auto & range : cell_ranges_data) {
854:         cell_count_check += range.second - range.first;
855:     }
856:     GGML_ASSERT(cell_count == cell_count_check);
857: 
858:     io.write(&cell_count, sizeof(cell_count));
859: 
860:     state_write_meta(io, cell_ranges, seq_id);
861:     state_write_data(io, cell_ranges_data);
862: }
