864: void llama_memory_recurrent::state_read(llama_io_read_i & io, llama_seq_id seq_id, llama_state_seq_flags flags) {
865:     GGML_UNUSED(flags);
866: 
867:     uint32_t cell_count;
868:     io.read(&cell_count, sizeof(cell_count));
869: 
870:     bool res = true;
871: 
872:     // save the head of the restored cells - could be needed to clear the state
873:     // the head is valid only when state_read_meta() succeeded
874:     const bool meta_read = state_read_meta(io, cell_count, seq_id);
875:     const uint32_t cell_head = head;
876: 
877:     res = res && meta_read;
878: 
879:     try {
880:         res = res && state_read_data(io, cell_count);
881:     } catch (...) {
882:         res = false;
883:     }
884: 
885:     if (!res) {
886:         state_clear(seq_id, cell_head, meta_read ? cell_count : 0);
887:         throw std::runtime_error("failed to restore kv cache");
888:     }
889: 
890:     if (n_rs_seq != 0) {
891:         set_rs_idx(seq_id, 0);
892:     }
893: }
