895: void llama_memory_recurrent::state_write_meta(llama_io_write_i & io, const std::vector<std::pair<uint32_t, uint32_t>> & cell_ranges, llama_seq_id seq_id) const {
896:     for (const auto & range : cell_ranges) {
897:         for (uint32_t i = range.first; i < range.second; ++i) {
898:             const auto & cell = cells[i];
899:             const llama_pos pos      = cell.pos;
900:             const uint32_t  n_seq_id = seq_id == -1 ? cell.seq_id.size() : 0;
901: 
902:             io.write(&pos,      sizeof(pos));
903:             io.write(&n_seq_id, sizeof(n_seq_id));
904: 
905:             if (n_seq_id) {
906:                 for (auto seq_id : cell.seq_id) {
907:                     io.write(&seq_id, sizeof(seq_id));
908:                 }
909:             }
910:         }
911:     }
912: }
