2070: void llama_kv_cache::state_write(llama_io_write_i & io, llama_seq_id seq_id, llama_state_seq_flags flags) const {
2071:     // TODO: refactor [TAG_KV_CACHE_SHARE_CELLS]
2072:     if (other) {
2073:         return;
2074:     }
2075: 
2076:     if ((flags & LLAMA_STATE_SEQ_FLAGS_PARTIAL_ONLY) && swa_type == LLAMA_SWA_TYPE_NONE) {
2077:         return;
2078:     }
2079: 
2080:     io.write(&n_stream, sizeof(n_stream));
2081: 
2082:     for (uint32_t s = 0; s < n_stream; ++s) {
2083:         cell_ranges_t cr { s, {} };
2084: 
2085:         uint32_t cell_count = 0;
2086: 
2087:         const auto & cells = v_cells[s];
2088: 
2089:         // Count the number of cells with the specified seq_id
2090:         // Find all the ranges of cells with this seq id (or all, when -1)
2091:         uint32_t cell_range_begin = cells.size();
2092: 
2093:         for (uint32_t i = 0; i < cells.size(); ++i) {
2094:             bool add_cell = true;
2095: 
2096:             add_cell = add_cell && !cells.is_empty(i);
2097:             add_cell = add_cell && (seq_id == -1 || cells.seq_has(i, seq_id));
2098: 
2099:             // check the cell is not SWA-masked
2100:             if (add_cell && seq_id != -1) {
2101:                 const bool is_masked = llama_hparams::is_masked_swa(n_swa, swa_type, cells.pos_get(i), cells.seq_pos_max(seq_id));
2102: 
2103:                 add_cell = !is_masked;
2104:             }
2105: 
2106:             if (add_cell) {
2107:                 ++cell_count;
2108:                 if (cell_range_begin == cells.size()) {
2109:                     cell_range_begin = i;
2110:                 }
2111:             } else {
2112:                 if (cell_range_begin != cells.size()) {
2113:                     cr.data.emplace_back(cell_range_begin, i);
2114:                     cell_range_begin = cells.size();
2115:                 }
2116:             }
2117:         }
2118: 
2119:         if (cell_range_begin != cells.size()) {
2120:             cr.data.emplace_back(cell_range_begin, cells.size());
2121:         }
2122: 
2123:         // DEBUG CHECK: Sum of cell counts in ranges should equal the total cell count
2124:         uint32_t cell_count_check = 0;
2125:         for (const auto & range : cr.data) {
2126:             cell_count_check += range.second - range.first;
2127:         }
2128:         GGML_ASSERT(cell_count == cell_count_check);
2129: 
2130:         io.write(&cell_count, sizeof(cell_count));
2131: 
2132:         // skip empty streams
2133:         if (cell_count == 0) {
2134:             continue;
2135:         }
2136: 
2137:         state_write_meta(io, cr, seq_id);
2138:         state_write_data(io, cr);
2139:     }
2140: }
