2146: void llama_kv_cache::state_read_sinfo(
2147:         llama_io_read_i & io,
2148:            llama_seq_id   seq_id,
2149:   llama_state_seq_flags   flags,
2150:       slot_info_vec_t *   sinfos_out,
2151: const slot_info_vec_t *   sinfos_in) {
