2153:     if (other) {
2154:         return;
2155:     }
2156: 
2157:     if ((flags & LLAMA_STATE_SEQ_FLAGS_PARTIAL_ONLY) && swa_type == LLAMA_SWA_TYPE_NONE) {
2158:         return;
2159:     }
2160: 
2161:     // TODO: fix incosistent handling of `seq_id < 0` and `seq_id == -1` in the codebase [TAG_LLAMA_SEQ_ID_NEG]
2162:     GGML_ASSERT(seq_id == -1 || (seq_id >= 0 && (size_t) seq_id < seq_to_stream.size()));
2163: 
2164:     if (sinfos_out) {
2165:         sinfos_out->assign(n_stream, slot_info{});
2166:     }
