2168:     if (sinfos_in && sinfos_in->size() != n_stream) {
2169:         throw std::runtime_error("failed to restore kv cache: mirrored slot layout has the wrong stream count");
2170:     }
2171: 
2172:     uint32_t n_stream_cur;
2173:     io.read(&n_stream_cur, sizeof(n_stream_cur));
2174:     if (n_stream_cur != n_stream) {
2175:         throw std::runtime_error("n_stream mismatch");
