1839:     const int lcp_best = prompt.tokens.get_common_prefix(tokens_new);
1840: 
1841:     float f_keep_best = prompt.tokens.size() > 0 ? float(lcp_best) / prompt.tokens.size() : -1.0f; // empty slot: any cache entry wins
1842:     float f_sim_best  = float(lcp_best) / tokens_new.size();
1843: 
1844:     SRV_TRC(" - looking for better prompt, base f_keep = %.3f, f_sim = %.3f\n", f_keep_best, f_sim_best);
1845: 
1846:     auto it_best = states.end();
1847: 
1848:     // find the most similar cached prompt, that would also preserve the most context
1849:     for (auto it = states.begin(); it != states.end(); ++it) {
1850:         const int lcp_cur = it->prompt.tokens.get_common_prefix(tokens_new);
1851: 
1852:         const float f_keep_cur = float(lcp_cur) / it->prompt.tokens.size();
1853:         const float f_sim_cur  = float(lcp_cur) / tokens_new.size();
1854: 
1855:         SRV_TRC("   - prompt with length %7zu, lcp = %7d, f_keep = %.3f, f_sim = %.3f\n", it->prompt.tokens.size(), lcp_cur, f_keep_cur, f_sim_cur);
1856: 
1857:         // don't trash large prompts
1858:         if (f_keep_cur < 0.25f) {
1859:             continue;
1860:         }
1861: 
1862:         if (f_keep_best < f_keep_cur && f_sim_best < f_sim_cur) {
1863:             f_keep_best = f_keep_cur;
1864:             f_sim_best  = f_sim_cur;
1865: 
1866:             it_best = it;
1867:         }
1868:     }
1869: 
1870:     if (it_best != states.end()) {
1871:         SRV_TRC(" - found better prompt with f_keep = %.3f, f_sim = %.3f\n", f_keep_best, f_sim_best);
1872: 
1873:         {
1874:             auto & data = it_best->data.main;
1875: 
1876:             const size_t size = data.size();
1877:             const size_t n = llama_state_seq_set_data_ext(ctx_tgt, data.data(), size, id_slot, 0);
1878:             if (n != size) {
1879:                 SRV_ERR("failed to restore state with size %zu\n", size);
1880: 
1881:                 return false;
1882:             }
1883: 
1884:             data.clear();
1885:             data.shrink_to_fit();
1886:         }
1887: 
1888:         {
1889:             auto & data = it_best->data.drft;
1890: 
1891:             if (!data.empty()) {
1892:                 GGML_ASSERT(ctx_dft);
1893: 
1894:                 const size_t size = data.size();
1895:                 const size_t n = llama_state_seq_set_data_ext(ctx_dft, data.data(), size, id_slot, 0);
1896:                 if (n != size) {
1897:                     SRV_WRN("failed to restore state with size %zu\n", size);
1898: 
1899:                     return false;
1900:                 }
1901: 
1902:                 data.clear();
1903:                 data.shrink_to_fit();
1904:             }
1905:         }
1906: 
1907:         prompt = std::move(it_best->prompt);
1908: 
1909:         states.erase(it_best);
1910:     }
1911: 
1912:     return true;
1913: }
